// Move the original cards, retaining playback handlers and cover observers.
export function createCardDecks({list,pendingGroup,pendingItems,pendingToggle,openBrowser,isFullscreen}){
 let categorized=false,categories={},query='';const groups=new Map();
 const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
 function positions(root){return new Map([...root.querySelectorAll('.library-score')].filter(c=>!c.hidden).slice(0,100).map(c=>[c,c.getBoundingClientRect()]));}
 function deal(root,change){const before=positions(root);change();if(reduced())return;const after=positions(root);let i=0;for(const [card,box]of after){const old=before.get(card);if(!old||!box.width||!box.height||Math.abs(old.left-box.left)+Math.abs(old.top-box.top)<1)continue;card._stackMotion?.cancel();card._stackMotion=card.animate([{translate:`${old.left-box.left}px ${old.top-box.top}px`,rotate:'-5deg'},{translate:'0px 0px',rotate:'0deg'}],{duration:560,delay:Math.min(i++*24,240),easing:'cubic-bezier(.18,.8,.24,1)'});}}
 function decorate(group,items,toggle,label){group.classList.add('library-card-stack');toggle.classList.add('card-stack-toggle');toggle.setAttribute('aria-label',label);toggle.onclick=async()=>{if(!isFullscreen())await openBrowser();deal(group,()=>{const expanded=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(expanded));group.classList.toggle('is-expanded',expanded);for(const card of items.children)card.inert=!expanded;});};items.classList.add('card-stack-items');group.addEventListener('click',event=>{if(!group.classList.contains('is-expanded')&&!event.target.closest('button'))toggle.click();});}
 decorate(pendingGroup,pendingItems,pendingToggle,'展开未就绪曲谱');
 function stack(label){if(groups.has(label))return groups.get(label);const group=document.createElement('section');group.className='library-card-stack library-category-stack';const toggle=document.createElement('button');toggle.type='button';toggle.className='card-stack-toggle';toggle.setAttribute('aria-expanded','false');const name=document.createElement('span');name.textContent=label;const count=document.createElement('small');toggle.append(name,count);const items=document.createElement('div');items.className='card-stack-items';group.append(toggle,items);decorate(group,items,toggle,'展开'+label);const value={group,items,toggle};groups.set(label,value);return value;}
 function regroup(){
  const cards=[...list.querySelectorAll('.library-score')];
  for(const card of cards){card.hidden=!!query&&!String(card._item?.title||'').toLowerCase().includes(query);if(card.dataset.ready!=='true')pendingItems.append(card);else if(categorized){stack(categories[card.dataset.scoreId]||'待分类').items.append(card);}else {card.inert=false;list.insertBefore(card,pendingGroup.parentElement===list?pendingGroup:null);}}
  for(const [label,{group,items,toggle}]of groups){if(categorized&&items.children.length){toggle.querySelector('small').textContent=items.children.length+' 首';group.hidden=![...items.children].some(c=>!c.hidden);list.append(group);}else{group.remove();groups.delete(label);}}
  pendingToggle.querySelector('small').textContent=pendingItems.children.length+' 首';pendingGroup.hidden=![...pendingItems.children].some(c=>!c.hidden);if(pendingItems.children.length)list.append(pendingGroup);else pendingGroup.remove();
  list.classList.toggle('library-categorized',categorized);
  for(const group of [...groups.values()].map(x=>x.group).concat(pendingGroup)){let n=0;for(const card of group.querySelectorAll('.library-score')){if(card.hidden)continue;card.inert=!group.classList.contains('is-expanded');card.style.setProperty('--stack-order',n);card.classList.toggle('stack-peek',n<4);n++;}}
 }
 return {regroup,reset(){categorized=false;query='';pendingGroup.classList.remove('is-expanded');pendingToggle.setAttribute('aria-expanded','false');regroup();},clear(){for(const value of groups.values())value.group.remove();groups.clear();},get categorized(){return categorized;},setCategorized(value){categorized=value;deal(list,regroup);},setCategories(value){categories=value;if(categorized)deal(list,regroup);},search(value){query=value;regroup();}};
}
